// <svg> of one glyph, placed absolutely inside a position:relative slot of g.s x g.s design px (colour = currentColor, except the logo / table keep their own)
export const RailGlyph = ({ name }) => {
  const g = RAIL_GLYPHS[name];
  return (
    <svg className="fr-g" width={g.w} height={g.h} viewBox={g.vb} style={g.c ? { left: g.l, top: g.t, color: g.c } : { left: g.l, top: g.t }} aria-hidden="true" focusable="false">{g.body}</svg>
  );
};
